#!/bin/bash
#
# Measures the Apple TV app on the simulator (docs/apple-tv.md, "Performance").
#
#   pnpm verify:tv --install                  # a Release build, installed
#   scripts/perf/tv/run.sh                    # every test
#   scripts/perf/tv/run.sh test03_PlayListFocusMoves test05_SeasonAndResult
#
# Drives the installed app with XCUIRemote from a UI-test bundle generated by
# XcodeGen (`brew install xcodegen`) into a scratch folder, samples the app's
# CPU time and resident memory from the host while it does (sample.sh), and
# prints each measured block: wall time, CPU, CPU per remote press, memory.
# Release builds only: a Debug build measures the development runtime, not
# the app. The simulator flatters an Apple TV HD several times over; compare
# runs with each other, never with a budget written for the hardware.
set -uo pipefail

HERE="$(cd "$(dirname "$0")" && pwd)"
export DEVELOPER_DIR="${DEVELOPER_DIR:-/Applications/Xcode.app/Contents/Developer}"
DEVICE="${TV_SIMULATOR:-Apple TV 4K (4th generation) (at 1080p)}"
OUT="${PERF_OUT:-${TMPDIR:-/tmp}/17-0-tv-perf}"

command -v xcodegen >/dev/null || { echo 'Needs XcodeGen: brew install xcodegen'; exit 1; }
UDID=$(xcrun simctl list devices available | grep -F "$DEVICE (" | grep -oE '[0-9A-F-]{36}' | head -1)
[[ -n "$UDID" ]] || { echo "No simulator named '$DEVICE'"; exit 1; }
xcrun simctl boot "$UDID" 2>/dev/null || true
xcrun simctl bootstatus "$UDID" >/dev/null
xcrun simctl get_app_container "$UDID" com.eighteenzerodcai.app >/dev/null 2>&1 \
  || { echo 'The app is not installed: pnpm verify:tv --install'; exit 1; }

mkdir -p "$OUT"
rm -rf "$OUT/project" && mkdir -p "$OUT/project"
cp -R "$HERE/project.yml" "$HERE/TVPerfUITests" "$OUT/project/"
(cd "$OUT/project" && xcodegen generate --quiet) || exit 1

only=()
for t in "$@"; do only+=("-only-testing:TVPerfUITests/TVPerf/$t"); done

stamp=$(date +%Y%m%d-%H%M%S)
log="$OUT/run-$stamp.log"
# The app's own console, for anything it logs while measured.
xcrun simctl spawn "$UDID" log stream --style compact \
  --predicate 'process == "SeventeenZero" AND eventMessage CONTAINS "[perf]"' > "$OUT/app-$stamp.log" 2>&1 &
streamer=$!
"$HERE/sample.sh" > "$OUT/samples-$stamp.txt" &
sampler=$!

xcodebuild test -project "$OUT/project/TVPerf.xcodeproj" -scheme TVPerf \
  -destination "id=$UDID" -derivedDataPath "$OUT/dd" -resultBundlePath "$OUT/result-$stamp.xcresult" \
  ${only[@]+"${only[@]}"} > "$log" 2>&1
status=$?
kill "$streamer" "$sampler" 2>/dev/null

echo
grep -E "^Test Case .*(passed|failed)|error:" "$log" | sed -E "s/^Test Case '-\[TVPerfUITests.TVPerf (.*)\]' /\1 /"
grep -E "^PERF " "$log" | grep -vE "^PERF (begin|end) " | sed 's/^/  /'
echo
python3 "$HERE/attribute.py" "$log" "$OUT/samples-$stamp.txt"
echo
echo "  log: $log"
echo "  app: $OUT/app-$stamp.log"
exit $status
